"""Authorization matrix: every (actor, request) pair has an expected status. Generated by `eos scaffold security-tests`.

Why: broken access control (OWASP A01; API1 BOLA, API3 BOPLA, API5 BFLA) is rarely found by scanners. This test
makes the rules explicit and fails when a new route has no row. See .eos/packs/ref/security/authorization.md.

Wire it up (once):
1. Implement `authz_client` below so `authz_client(actor)` returns something with
   `.request(method, path, json=None) -> response` (with `.status_code`) authenticated as that actor.
   FastAPI/Starlette: TestClient + a login helper; Django: `Client.force_login`; Flask: `app.test_client()`.
2. Implement `seed` to create two tenants, two customers in tenant 1 and one in tenant 2, and their objects;
   return the ids used in MATRIX paths.
3. Implement `app_routes` to list (method, path_template) from your router so new routes must be added here.
Until wired, the tests skip with a message (they never pass silently).
"""

import pytest

# (actor, method, path template, expected status). Use 404 (not 403) for objects the actor may not see.
MATRIX = [
    ("anonymous", "GET", "/invoices/{own_invoice}", 401),
    ("customer_a", "GET", "/invoices/{own_invoice}", 200),
    ("customer_a", "GET", "/invoices/{same_tenant_other_user_invoice}", 404),  # BOLA / IDOR
    ("customer_a", "GET", "/invoices/{other_tenant_invoice}", 404),  # cross-tenant
    ("customer_a", "DELETE", "/invoices/{same_tenant_other_user_invoice}", 404),
    ("customer_a", "POST", "/admin/refunds", 403),  # BFLA
    ("support", "GET", "/invoices/{same_tenant_other_user_invoice}", 200),
    ("support", "GET", "/invoices/{other_tenant_invoice}", 404),
    ("admin", "POST", "/admin/refunds", 201),
]

# Fields a client must never be able to set (BOPLA / mass assignment).
PROTECTED_FIELDS = {"role": "admin", "is_admin": True, "tenant_id": "other", "balance": 10**9, "status": "verified"}
SELF_UPDATE = ("PATCH", "/me")
SELF_READ = ("GET", "/me")


@pytest.fixture
def seed():
    pytest.skip("wire `seed` in tests/security/test_authz_matrix.py (see module docstring)")


@pytest.fixture
def authz_client():
    pytest.skip("wire `authz_client` in tests/security/test_authz_matrix.py (see module docstring)")


@pytest.fixture
def app_routes():
    pytest.skip("wire `app_routes` to list your router's (method, path) pairs")


@pytest.mark.parametrize(("actor", "method", "path", "expected"), MATRIX)
def test_authorization_matrix(authz_client, seed, actor, method, path, expected):
    resp = authz_client(actor).request(method, path.format(**seed))
    assert resp.status_code == expected, f"{actor} {method} {path}: got {resp.status_code}, want {expected}"


def test_protected_fields_cannot_be_mass_assigned(authz_client, seed):
    client = authz_client("customer_a")
    before = client.request(*SELF_READ).json()
    client.request(*SELF_UPDATE, json=PROTECTED_FIELDS)
    after = client.request(*SELF_READ).json()
    for field in PROTECTED_FIELDS:
        assert after.get(field) == before.get(field), f"client changed protected field {field!r}"


def test_every_route_has_a_matrix_row(app_routes):
    covered = {(m, p.split("{")[0].rstrip("/")) for _, m, p, _ in MATRIX}
    missing = [(m, p) for m, p in app_routes if (m, p.split("{")[0].rstrip("/")) not in covered]
    assert not missing, f"routes without an authorization row in MATRIX: {missing}"
